<template>
  <section class="rbac-page">
    <header class="page-head"><div><router-link to="/super-admin/rbac">← 返回权限组织</router-link><h2>职工个人授权</h2></div><div class="object-badge"><small>当前对象 · 职工</small><strong>{{ currentObject }}</strong></div></header>
    <div v-if="error" class="banner banner--error">{{ error }}</div><div v-if="message" class="banner">{{ message }}</div>
    <section class="panel search-panel"><div class="search-row"><input v-model.trim="keyword" placeholder="搜索职工姓名 / 手机号 / 邮箱" @keyup.enter="search"/><button class="button" @click="search">搜索职工</button></div><div v-if="users.length" class="results"><button v-for="user in users" :key="user.id" :class="{active:user.id===selectedUserId}" @click="selectUser(user.id)"><strong>{{ user.name||'未命名用户' }}</strong><span>{{ user.type_name||'未设置职位' }} · {{ user.phone||user.email }}</span></button></div></section>
    <section v-if="selectedUserId" class="panel workbench"><div class="permission-pane"><div><strong>个人权限</strong><p>职位默认权限不可取消；个人授权只显示该职位允许加授的权限。</p></div><div v-if="hiddenCount" class="boundary-note">医疗 / 仓储等 {{ hiddenCount }} 项权限不在此职位授权边界内，已隐藏</div><div class="permission-groups"><section v-for="group in groups" :key="group.name"><h3>{{ group.name }}</h3><div class="permission-list"><label v-for="key in group.keys" :key="key" class="permission-item" :class="{active:key===activeKey,locked:positionPermissions.includes(key)}" @mouseenter="activeKey=key"><input type="checkbox" :checked="positionPermissions.includes(key)||personal.includes(key)" :disabled="positionPermissions.includes(key)" @focus="activeKey=key" @change="toggle(key)"/><span>{{ label(key) }}</span><b v-if="positionPermissions.includes(key)">职位默认</b></label></div></section></div><div class="actions"><button class="button" @click="diffOpen=true">保存个人授权</button><button class="button button--ghost" @click="clearPersonal">清空个人加授（回到职位默认）</button></div></div>
      <aside class="help"><strong>权限说明</strong><template v-if="activeMeta"><h3>{{ activeMeta.label }}</h3><code>{{ activeKey }}</code><p>{{ activeMeta.desc }}</p><div class="boundary">能力边界：个人加授不能越过当前职位的业务域；组织数据范围仍独立控制。</div><div v-if="activeMeta.danger" class="warning">⚠ 高危权限：授予前请确认本人确有需要。</div></template><p v-else class="empty">聚焦任一权限查看中文含义与边界。</p></aside></section>
    <section v-if="selectedUserId" class="panel assignment"><div class="panel-title">用户派岗与范围</div><div class="assignment-grid"><div class="assignment-block"><label><span>职位</span><select v-model.number="selectedUserPositionId"><option :value="0">普通用户</option><option v-for="p in positions" :key="p.id" :value="p.id">{{ p.name }} / {{ p.department_name }}</option></select></label><div class="inline-action"><button class="button" @click="savePosition">保存派岗</button><small>调职会清空该职工的个人加授</small></div></div><div class="assignment-block"><strong>可见分院</strong><div class="scope-list"><label v-for="b in branches" :key="b.id"><input type="checkbox" :checked="scopeBranchIds.includes(b.id)" @change="toggleScope(scopeBranchIds,b.id)"/>{{ b.name }}</label></div><strong>可见部门</strong><div class="scope-list"><label v-for="d in departments" :key="d.id"><input type="checkbox" :checked="scopeDepartmentIds.includes(d.id)" @change="toggleScope(scopeDepartmentIds,d.id)"/>{{ d.name }}</label></div><button class="button" @click="saveScopes">保存范围</button></div></div></section>
    <PermissionDiffDialog :open="diffOpen" title="确认个人授权差异" :added="added" :removed="removed" :saving="saving" @cancel="diffOpen=false" @confirm="savePersonal"/>
  </section>
</template>
<script lang="ts">
import { computed, defineComponent, onMounted, ref } from "vue";
import PermissionDiffDialog from "@/modules/super-admin/components/PermissionDiffDialog.vue";import { superAdminApi } from "@/modules/super-admin/api/superAdminApi";import type { RbacDepartment,RbacPosition,UserRow } from "@/modules/super-admin/api/types";import { PERMISSION_META,permissionGroups,permissionLabel } from "@/modules/super-admin/utils/permissionMeta";
export default defineComponent({name:"SuperAdminRbacUsers",components:{PermissionDiffDialog},setup(){
 const users=ref<UserRow[]>([]),positions=ref<RbacPosition[]>([]),departments=ref<RbacDepartment[]>([]),catalog=ref<string[]>([]);const keyword=ref(""),selectedUserId=ref(0),selectedUserPositionId=ref(0),positionName=ref(""),departmentName=ref(""),positionPermissions=ref<string[]>([]),personal=ref<string[]>([]),snapshot=ref<string[]>([]),grantable=ref<string[]>([]),scopeBranchIds=ref<number[]>([]),scopeDepartmentIds=ref<number[]>([]),activeKey=ref(""),error=ref(""),message=ref(""),diffOpen=ref(false),saving=ref(false);
 const selectedUser=computed(()=>users.value.find(u=>u.id===selectedUserId.value));const currentObject=computed(()=>selectedUser.value?`${selectedUser.value.name||'未命名用户'} · ${positionName.value||selectedUser.value.type_name||'未设置职位'} · ${departmentName.value||'未分部门'}`:"请先搜索并选择职工");const branches=computed(()=>{const m=new Map<number,string>();departments.value.forEach(d=>{if(d.branch_id>0)m.set(d.branch_id,d.branch_name||`分院 ${d.branch_id}`)});return Array.from(m,([id,name])=>({id,name}))});const visibleKeys=computed(()=>Array.from(new Set([...grantable.value,...positionPermissions.value])));const groups=computed(()=>permissionGroups(visibleKeys.value));const hiddenCount=computed(()=>catalog.value.filter(k=>!visibleKeys.value.includes(k)).length);const activeMeta=computed(()=>activeKey.value?(PERMISSION_META[activeKey.value]||{label:activeKey.value,desc:"暂无中文说明。",group:"其他"}):null);const added=computed(()=>personal.value.filter(k=>!snapshot.value.includes(k)));const removed=computed(()=>snapshot.value.filter(k=>!personal.value.includes(k)));
 const search=async()=>{try{const r=await superAdminApi.searchUsers({keyword:keyword.value,role:"all",page:1,pageSize:20,includeCounts:false});users.value=r.items;error.value=""}catch(e){error.value=e instanceof Error?e.message:"搜索职工失败"}};
 const loadUser=async()=>{const [p,s]=await Promise.all([superAdminApi.getUserRbacPermissions(selectedUserId.value),superAdminApi.getUserScopes(selectedUserId.value)]);selectedUserPositionId.value=p.positionId;positionName.value=p.positionName;departmentName.value=p.departmentName;positionPermissions.value=p.positionPermissions;personal.value=p.personalPermissions;snapshot.value=[...p.personalPermissions];grantable.value=p.grantableKeys;scopeBranchIds.value=s.branch_ids;scopeDepartmentIds.value=s.department_ids;activeKey.value=visibleKeys.value[0]||""};const selectUser=async(id:number)=>{selectedUserId.value=id;try{await loadUser();error.value=""}catch(e){error.value=e instanceof Error?e.message:"加载职工授权失败"}};
 const toggle=(key:string)=>{activeKey.value=key;if(positionPermissions.value.includes(key))return;personal.value=personal.value.includes(key)?personal.value.filter(v=>v!==key):[...personal.value,key]};
 const savePersonal=async()=>{saving.value=true;try{await superAdminApi.updateUserRbacPermissions(selectedUserId.value,personal.value);snapshot.value=[...personal.value];diffOpen.value=false;message.value="个人授权已保存，该职工需重新登录后生效";error.value=""}catch(e){error.value=e instanceof Error?e.message:"保存个人授权失败";diffOpen.value=false}finally{saving.value=false}};
 const clearPersonal=async()=>{if(!window.confirm("确认清空该职工全部个人加授，回到职位默认权限？"))return;try{await superAdminApi.updateUserRbacPermissions(selectedUserId.value,[]);personal.value=[];snapshot.value=[];message.value="个人加授已清空，该职工需重新登录后生效"}catch(e){error.value=e instanceof Error?e.message:"清空个人授权失败"}};
 const savePosition=async()=>{if(!window.confirm("调职会清空该职工的个人加授，确认保存派岗？"))return;try{await superAdminApi.updateUserPosition(selectedUserId.value,selectedUserPositionId.value||null);await search();await loadUser();message.value="职工派岗已保存，个人加授已清空"}catch(e){error.value=e instanceof Error?e.message:"保存派岗失败"}};const toggleScope=(items:number[],id:number)=>{const i=items.indexOf(id);i>=0?items.splice(i,1):items.push(id)};const saveScopes=async()=>{try{await superAdminApi.updateUserScopes(selectedUserId.value,{branch_ids:scopeBranchIds.value,department_ids:scopeDepartmentIds.value});message.value="用户组织范围已保存"}catch(e){error.value=e instanceof Error?e.message:"保存组织范围失败"}};
 onMounted(async()=>{try{[positions.value,departments.value,catalog.value]=await Promise.all([superAdminApi.getRbacPositions(),superAdminApi.getRbacDepartments(),superAdminApi.getPermissionCatalog()]);await search()}catch(e){error.value=e instanceof Error?e.message:"加载页面数据失败"}});return{users,positions,departments,keyword,selectedUserId,selectedUserPositionId,positionPermissions,personal,scopeBranchIds,scopeDepartmentIds,activeKey,activeMeta,currentObject,branches,groups,hiddenCount,added,removed,diffOpen,saving,error,message,label:permissionLabel,search,selectUser,toggle,savePersonal,clearPersonal,savePosition,toggleScope,saveScopes};
}});
</script>
<style scoped>
