ermission-item.active{border-color:#2f7dd0;background:#f1f6fd}.permission-item.locked{background:#f0f4f8;color:#52677d}.permission-item input{accent-color:#2f7dd0}.permission-item b{margin-left:auto;color:#2f7dd0;font-size:11px}.actions{display:flex;gap:10px;margin-top:16px}.help{align-self:start;position:sticky;top:0;padding:16px;border:1px solid #d7e3f2;border-radius:12px;background:#f7fafd}.help>strong{color:#55708d;font-size:12px}.help h3{margin:14px 0 5px}.help code{color:#2263ad;background:#e6eff9;padding:3px 7px;border-radius:6px}.help p,.boundary{color:#4e6680;font-size:13px;line-height:1.65}.boundary{padding-top:10px;border-top:1px solid #d7e3f2}.warning{margin-top:10px;padding:9px;background:#fff3d8;border-radius:8px;color:#9b5700;font-size:12px;font-weight:800}.panel-title{padding-bottom:10px;border-bottom:1px solid #d7e3f2;font-weight:800}.assignment-grid{display:grid;grid-template-columns:minmax(280px,.7fr) 1.3fr;gap:18px;margin-top:14px}.assignment-block{display:grid;align-content:start;gap:10px}.assignment-block>label{display:grid;gap:6px}.inline-action{display:flex;align-items:center;gap:10px}.inline-action small{color:#9b5700}.scope-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:7px}.scope-list label{padding:7px;border:1px solid #d7e3f2;border-radius:8px}.scope-list input{accent-color:#2f7dd0}.banner{padding:10px 12px;border:1px solid #cfe0f5;border-radius:9px;background:#eaf3fd;color:#1e5aa0}.banner--error{border-color:#fecaca;background:#fef2f2;color:#991b1b}@media(max-width:1000px){.page-head{align-items:stretch;flex-direction:column}.workbench,.assignment-grid{grid-template-columns:1fr}.help{position:static}.object-badge{min-width:0}}
